// Search worker for the Chinese site, in place of the theme's lunr worker of
// the same name. lunr splits text into words at whitespace and punctuation,
// and Chinese puts no space between words, so a whole sentence becomes one
// token and a word inside it is never found. This worker matches substrings
// instead, which finds a Chinese word wherever it appears and an English
// identifier as before.
//
// It speaks the theme's protocol (docfx modern template, public/search.min.js):
// {init} loads the index and answers {e: 'index-ready'}; {q} answers
// {e: 'query-ready', d: entries}, the matching entries of index.json, best
// first. The query arrives as lunr syntax: the theme prefixes every typed word
// with '+', so a word typed with a leading '-' arrives as '+-word'.
// .github/scripts/docs-i18n.py check warns when a built theme no longer
// mentions these messages.

let pages = [];

async function load() {
    const res = await fetch('../index.json');
    const index = await res.json();
    pages = Object.values(index).map(page => ({
        page,
        title: (page.title ?? '').toLowerCase(),
        // docfx puts the page's whole text in summary.
        text: (page.summary ?? '').toLowerCase(),
    }));
    postMessage({ e: 'index-ready' });
}

function occurrences(text, term) {
    let count = 0;
    for (let at = text.indexOf(term); at !== -1 && count < 20; at = text.indexOf(term, at + term.length)) {
        count++;
    }
    return count;
}

function parse(query) {
    const required = [];
    const excluded = [];
    for (const word of query.toLowerCase().split(/\s+/)) {
        const term = word.replace(/^\+/, '');
        if (term.startsWith('-')) {
            if (term.length > 1) {
                excluded.push(term.slice(1));
            }
        } else if (term !== '') {
            required.push(term);
        }
    }
    return { required, excluded };
}

// Every required word must appear in the page and no excluded one. A word in
// the title weighs 50, and each of its first 20 occurrences in the text 1.
function search(query) {
    const { required, excluded } = parse(query);
    if (required.length === 0) {
        return [];
    }
    const results = [];
    for (const entry of pages) {
        if (excluded.some(term => entry.title.includes(term) || entry.text.includes(term))) {
            continue;
        }
        let score = 0;
        for (const term of required) {
            const inTitle = entry.title.includes(term) ? 50 : 0;
            const inText = occurrences(entry.text, term);
            if (inTitle + inText === 0) {
                score = 0;
                break;
            }
            score += inTitle + inText;
        }
        if (score > 0) {
            results.push({ score, page: entry.page });
        }
    }
    return results.sort((a, b) => b.score - a.score).map(result => result.page);
}

onmessage = event => {
    if (event.data.q !== undefined) {
        postMessage({ e: 'query-ready', d: search(event.data.q) });
    } else if (event.data.init) {
        load().catch(console.error);
    }
};
